void main() {
  final routes = [
    NavigationData(
      url: '/',
      builder: (context, routeData, globalData) => const HomeScreen(),
    ),
    NavigationData(
      url: '/details/:id',
      builder: (context, routeData, globalData) => DetailsScreen(
        id: routeData.pathParameters['id'],
      ),
    ),
  ];

  NavigationManager.init(
    mainRouterDelegate: DefaultRouterDelegate(navigationDataRoutes: routes),
    routeInformationParser: DefaultRouteInformationParser(),
  );

  runApp(MaterialApp.router(
    routerDelegate: NavigationManager.instance.routerDelegate,
    routeInformationParser: NavigationManager.instance.routeInformationParser,
  ));
}
